;===================================================================================================
; Crystal maiden in Swamp Palace
;===================================================================================================
; [LINK] あなたのおかげで
; 魔族の手から,のがれる事が
; できました。ありがとう⋯。
; ⋯トライフォースは,それに
; ふれた者の願いをかなえます。
; その者が生きているかぎり⋯。
; だからこそ,聖地におかれ
; 選ばれた者だけにその場所が
; 伝えられてきたの。
; ところが,それがどこかで
; とぎれてしまったみたい⋯。
; そして,再び聖地をみつけた
; のが,ガノンドロフと言う
; 盗賊だったのよ。
; でも,幸いな事に彼は光の世界
; へ帰る方法がわからなかったの
; ⋯そう,思い出して。
; あなたは,勇者だけが使いこな
; せるマジカルミラーをもってい
; るじゃない!
; ヘブラ山にあった魔法陣が,
; 他にもいくつかあるの。
; それを使って2つの世界を行き
; 来すれば,闇の世界にひそむ
; 魔物達も探しだせるわ!
; 盗賊ガノンドロフ⋯いいえ,
; 闇の魔王ガノンを倒せるのは
; あなただけ⋯祈っています。
;===================================================================================================
