;===================================================================================================
; Crystal maiden in Skull Woods
;===================================================================================================
; [LINK] あなたのおかげで
; 魔族の手から,のがれる事が
; できました。ありがとう⋯。
; ⋯『オオイナル ワザワイ』の
; 予言は知っていますか?
; 私は,こうきいています⋯。
; もしも,悪しき心をもつ者が,
; トライフォースを手にするなら
; ば,『勇者』が必ず現れ,
; この『オオイナル ワザワイ』
; のもととなる者をうつであろう
; しかし,『勇者』が倒れた時は
; 悪しき心の者に世界は,おおわ
; れてしまうであろう,と⋯。
; そう,『勇者』になれるのは,
; ハイリアの王家を守っていた
; ナイトのー族の者だけのはず⋯
; あなたは,その血をひいていた
; のね。 ゼルダ姫を必ず救って
; あげてね。
;===================================================================================================
