;===================================================================================================
; [LINK] あなたのおかげで
; 魔族の手から,のがれる事が
; できました。ありがとう⋯。
; ハイリアの民は,ふしぎな力を
; あやつることが,できたと言い
; ます。7賢者もそうだったの。
; でも,長い年月の間にハイリア
; の血はうすれ,7賢者の血を
; ひく私達も強い力はありません
; ただ,勇気を司どるナイトの力
; があれば,知恵を司どる賢者の
; 力もより大きくなるはずよ!
; お城にできた,光と闇をつなぐ
; 道が,完全に開くまで
; もう,あまり時間がないわ。
; ガノンを倒せば,この闇の世界
; もなくなり,トライフォースは
; また,つぎの持ちぬしが,
; 現れるのをまっているはずです
; あなたを信じています。
; ⋯ がんばって⋯。
