; Crystal maiden in Misery Mire
;===================================================================================================
; [LINK] あなたのおかげで
; 魔族の手から,のがれる事が
; できました。ありがとう⋯。
; ガノンが私達を集めたのは,
; ガノンの力では7賢者の封印を
; やぶれなかったからなの。
; そこで,司祭アグニムを使って
; 賢者の力をうけつぐ娘7人を
; 闇世界におくりこませたの。
; 7人の力をりようして,封印を
; やぶったあと,ようがすんだ
; 私達はクリスタルに封じられ,
; 魔物達にあたえられたわ。ただ
; あなたの事を知らなかったのは
; ガノンのミスだったわね。
; さあ,ゼルダ姫がカメイワで
; あなたをまっています。
; 急いで行ってあげて下さい。
;===================================================================================================
