;===================================================================================================
; Zelda in Turtle Rock
;===================================================================================================
; [LINK],よくここまで来てく
; れました。 やっぱりあなたが
; 伝説の『勇者』だったのね。
; はじめて会った時から,そんな
; 気がしていました。
; ⋯ ⋯ ⋯
; ガノンは,デスマウンテンの塔
; に結界をはり,2つの世界の通
; り道をぬける時をまっています
; ガノンが光の世界へ出てしまっ
; たら,もう捕える事はできない
; かも知れないわ。
; でも,このとじた空間のなかな
; ら,どこへ逃げても必ず見付け
; る事ができます。
; さあ,7つのクリスタルをもっ
; て,ガノンの塔へ急ぎましょう
; 結界は,私達の力でやぶります
; [LINK] ⋯
; 必ず平和な国を
; とり戻しましょうね ⋯ ⋯
;===================================================================================================
