; ガノンが光の世界へ出てしまっ
; たら,もう捕える事はできない
; かも知れないわ。
; でも,このとじた空間のなかな
; ら,どこへ逃げても必ず見付け
; る事ができます。
; あなたの助けをまつ娘達が,ま
