|1CF50B| BNE .not_hooker

.yes_hooker
|1CF50D| LDA.w $037E
|1CF510| BEQ .not_hooker

.active_hooker
|1CF512| STZ.w $037E
|1CF515| BRA .stop_hooking

.not_hooker
|1CF517| DEX
|1CF518| BPL .next_ancilla

