;===================================================================================================
; Comes in with Y, a quota for maximum number of this ancilla
;===================================================================================================
FindAncillaSlot:
|1CF537| STY.b $0F

|1CF539| INY
|1CF53A| STY.b $0E

|1CF53C| LDY.b #$00
|1CF53E| LDX.b #$04

; tally each matching ancilla in the first 4 slots
.tallyoop
|1CF540| CMP.w $0C4A,X
|1CF543| BNE .not_the_same

|1CF545| INY

.not_the_same
|1CF546| DEX
|1CF547| BPL .tallyoop

; I guess, theoretically, the quota shouldn't be surpassable
; but if you somehow do it, this will not function as intended
|1CF549| CPY.b $0E
|1CF54B| BEQ .too_many_here

|1CF54D| LDY.b #$01 ; [HARDCODED] check for bomb or debris, limited to 2 slots
|1CF54F| CMP.b #$07 ; ANCILLA 07
|1CF551| BEQ .find_empty_slot

|1CF553| CMP.b #$08 ; ANCILLA 08
|1CF555| BEQ .find_empty_slot

|1CF557| LDY.b #$04 ; all other ancillae are designed to use any of the first 5

.find_empty_slot
|1CF559| LDA.w $0C4A,Y
|1CF55C| BEQ .slot_available

|1CF55E| DEY
|1CF55F| BPL .find_empty_slot

; otherwise, find an unimportant ancilla to replace
; here's the famous dumb code that allows for misslotting
; why search slots in this manner instead of just searching the same 5
; (or 2 in the case of bombs)
; the more you think about it, the less it makes sense
; this game's most broken class of glitches was pretty easily preventable
.check_next_replacement
|1CF561| DEC.w $03C4
|1CF564| BPL .continue_with_index

; use the quota as the index to search from
; this decision also makes 0 sense
; Why not 4...?
|1CF566| LDA.b $0F
|1CF568| STA.w $03C4

.continue_with_index
|1CF56B| LDY.w $03C4

|1CF56E| LDA.w $0C4A,Y
|1CF571| CMP.b #$3C ; ANCILLA 3C
|1CF573| BEQ .slot_available

|1CF575| CMP.b #$13 ; ANCILLA 13
|1CF577| BEQ .slot_available

|1CF579| CMP.b #$0A ; ANCILLA 0A
|1CF57B| BEQ .slot_available

|1CF57D| DEY
|1CF57E| BPL .check_next_replacement

.slot_available
|1CF580| RTL

;---------------------------------------------------------------------------------------------------

.too_many_here
|1CF581| TXY

|1CF582| RTL

